48	/// Returns an iterator of all supported config file names, in priority order.
49	///
50	/// When `VP_VERSION` env var is set, only `vite.config.ts` is recognized.
51	/// When it is not set, `vite.config.ts` is excluded from the candidates.
52	pub fn all_config_file_names() -> impl Iterator<Item = &'static str> {
53	    #[cfg(feature = "napi")]
54	    {
55	        if utils::vp_version().is_some() {
56	            return vec![VITE_PLUS_CONFIG_NAME].into_iter();
57	        }
58	        JSON_CONFIG_FILES
59	            .iter()
60	            .copied()
61	            .chain([OXFMT_JS_CONFIG_NAME])
62	            .collect::<Vec<_>>()
63	            .into_iter()
64	    }
65	    #[cfg(not(feature = "napi"))]
66	    JSON_CONFIG_FILES.iter().copied()
