79	/// If `cwd` is provided, relative Tailwind paths are resolved against it.
80	#[cfg(feature = "napi")]
81	pub fn resolve_options_from_value(
82	    raw_config: Value,
83	    strategy: &FormatFileStrategy,
84	    cwd: Option<&Path>,
85	) -> Result<ResolvedOptions, String> {
86	    let mut format_config: FormatConfig =
87	        serde_json::from_value(raw_config).map_err(|err| err.to_string())?;
88	    if let Some(cwd) = cwd {
89	        format_config.resolve_tailwind_paths(cwd);
90	    }
91	
92	    let mut external_options =
93	        serde_json::to_value(&format_config).expect("FormatConfig serialization should not fail");
94	    let oxfmt_options = to_oxfmt_options(format_config)?;
95	
96	    sync_external_options(&oxfmt_options.format_options, &mut external_options);
97	
98	    Ok(ResolvedOptions::from_oxfmt_options(oxfmt_options, external_options, strategy))
99	}
